def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    joined = []
    for i, (r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            dr, dc = r2-r1, c2-c1
            if dr != 0 and abs(dr) == abs(dc):
                joined.append((r1,c1,r2,c2))
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                r,c = r1,c1
                while True:
                    if grid[r][c] != 6:
                        out[r][c] = 1
                    if (r,c) == (r2,c2):
                        break
                    r += sr; c += sc

    # A 6 marker lying on a joined 1 segment draws the perpendicular diagonal.
    for r,c in sixes:
        for r1,c1,r2,c2 in joined:
            dr,dc = r2-r1,c2-c1
            if (r-r1)*dc == (c-c1)*dr and min(r1,r2) <= r <= max(r1,r2) and min(c1,c2) <= c <= max(c1,c2):
                slope = -1 if dr*dc > 0 else 1
                for rr in range(h):
                    for cc in range(w):
                        if (rr-r) == slope*(cc-c) and grid[rr][cc] != 1:
                            out[rr][cc] = 6
    # Restore the joined 1 lines over drawn diagonals, except original 6 markers.
    for r1,c1,r2,c2 in joined:
        dr,dc = r2-r1,c2-c1
