    """Overlay the two equal-sized panels divided by a uniform line.

    A cell is active only where both corresponding panel cells are nonzero.
    Active overlaps are recolored to 2.
    """
    h, w = len(grid), len(grid[0])
    # Prefer the unique full separator that leaves equal-sized panels.
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid):
