        if all(x == grid[r][0] for x in grid[r]):
            if r > 0 and h - r - 1 == r:
                return [[2 if grid[i][c] != 0 and grid[r + 1 + i][c] != 0 else 0
                         for c in range(w)] for i in range(r)]
    raise ValueError("no centered uniform separator with equal panels")

