def transform(grid):
    """Fill vertical gaps between consecutive cells of the sparse marker color."""
    from collections import Counter
    g = [row[:] for row in grid]
    counts = Counter(x for row in g for x in row)
    bg = counts.most_common(1)[0][0]
    h, w = len(g), len(g[0])
    for color in counts:
        if color == bg:
            continue
        for c in range(w):
            ys = [r for r in range(h) if g[r][c] == color]
            for a, b in zip(ys, ys[1:]):
                for r in range(a + 1, b):
                    if g[r][c] == bg:
                        g[r][c] = 3
    return g

