def transform(grid):
    from collections import Counter
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [list(row) for row in grid]
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))

    def end_and_runs(row):
        pos = [c for c,v in enumerate(row) if v != bg]
        if not pos:
            return -1, 0, 0
        runs = 1 + sum(1 for a,b in zip(pos,pos[1:]) if b > a+1)
        trailing = 1
        for a,b in zip(reversed(pos[:-1]), reversed(pos[1:])):
            if a == b-1:
                trailing += 1
            else:
                break
        return pos[-1], runs, trailing

    # Matched multi-row bands can reveal a cropped solid tail. Only treat
    # it as a crop when both rows have contiguous foreground runs at their ends.
    if len(bands) == 2 and (bands[0][1]-bands[0][0]) > 1 and (bands[0][1]-bands[0][0]) == (bands[1][1]-bands[1][0]):
        (a0, a1), (b0, b1) = bands
        for k in range(a1-a0):
            i, j = a0+k, b0+k
            ei, ri, ti = end_and_runs(grid[i]); ej, rj, tj = end_and_runs(grid[j])
            if ti >= 2 and tj >= 2:
                if ei > ej:
                    for c in range(ej+1, w):
                        if grid[i][c] != bg: out[j][c] = 1
                elif ej > ei:
                    for c in range(ei+1, w):
                        if grid[j][c] != bg: out[i][c] = 1
        return out

    # Otherwise, a row matching another row through its final foreground cell
    # is a truncated copy; mark the missing right tail.
    for i, row in enumerate(grid):
        end, _, _ = end_and_runs(row)
        if end < 0 or end == w-1:
            continue
        for j, other in enumerate(grid):
            if i == j or other[:end+1] != row[:end+1]:
                continue
            if any(v != bg for v in other[end+1:]):
                for c in range(end+1, w):
                    if other[c] != bg: out[i][c] = 1
                break
    return out

