            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, grid[y][x]))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] != bg:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append(comp)
    template = max(comps, key=len)
    y0, y1 = min(y for y,x,v in template), max(y for y,x,v in template)
    x0, x1 = min(x for y,x,v in template), max(x for y,x,v in template)
    cy, cx = (y0+y1)//2, (x0+x1)//2
    offsets = [(y-cy, x-cx, v) for y,x,v in template]
    out = [row[:] for row in grid]
    for comp in comps:
        if comp is template:
            continue
        for y, x, _ in comp:
            for dy, dx, v in offsets:
                yy, xx = y+dy, x+dx
                if 0 <= yy < h and 0 <= xx < w:
                    out[yy][xx] = v
    return out

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp = []
            touches_edge = False
            while q:
                y,x = q.popleft()
                comp.append((y,x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    touches_edge = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if not touches_edge:
                color = 7 if len(comp) % 2 else 2
                for y,x in comp:
                    out[y][x] = color
    return out

from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            area = (r1-r0+1)*(c1-c0+1)
            # Keep near-solid rectangular objects; isolated background noise is discarded.
            if area >= 4 and len(cells) >= 3 and len(cells)/area >= 0.68:
                rects.append((r0, r1, c0, c1, color))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in rects:
        for y in range(r0, r1+1):
            for x in range(c0, c1+1):
                out[y][x] = color
    return out

def transform(grid):
    out = [row[:] for row in grid]
    base = next((r for r, row in enumerate(grid) if any(v != 0 for v in row)), None)
    if base is None:
        return out
    for c, color in enumerate(grid[base]):
        if color not in (2, 8):
            continue
        height = 4 if color == 2 else 3
        top = max(0, base - height)
        out[top][c] = color
        for rr in range(top + 1, base):
            out[rr][c] = 1
    return out

def transform(grid):
    """Complete repeated horizontal bars to the longest observed right edge."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    # A solid horizontal run on an otherwise background row is a repeated bar.
    bars = {}
    for r, row in enumerate(grid):
        colors = {v for v in row if v != bg}
        if len(colors) != 1:
            continue
        color = next(iter(colors))
        inds = [c for c, v in enumerate(row) if v == color]
        if inds != list(range(inds[0], inds[-1] + 1)):
            continue
        if all(v == bg or v == color for v in row):
            bars.setdefault(color, []).append((r, inds[0], inds[-1]))
    for color, items in bars.items():
        max_end = max(end for _, _, end in items)
        for r, start, end in items:
            for c in range(end + 1, max_end + 1):
                if out[r][c] == bg:
                    out[r][c] = 1
    return out

def transform(grid):
    """Mark incomplete repeated horizontal patterns with color 1."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Horizontal solid bars: extend repeated bars to the furthest observed end.
    bars = {}
    for r, row in enumerate(grid):
        colors = {v for v in row if v != bg}
        if len(colors) != 1:
            continue
        color = next(iter(colors))
        inds = [c for c, v in enumerate(row) if v == color]
        if inds and inds == list(range(inds[0], inds[-1] + 1)):
            bars.setdefault(color, []).append((r, inds[-1]))
    for color, items in bars.items():
        max_end = max(end for _, end in items)
        for r, end in items:
            for c in range(end + 1, max_end + 1):
                if out[r][c] == bg:
                    out[r][c] = 1

    # For repeated row patterns with a long shared prefix, use the prevailing
    # foreground color in that prefix as the reference and mark deviations.
    for a in range(h):
        for b in range(a + 1, h):
            l = 0
            while l < w and grid[a][l] == grid[b][l]:
                l += 1
            if l < 3 or l == w:
                continue
            shared = [v for v in grid[a][:l] if v != bg]
            if not shared:
                continue
            key = Counter(shared).most_common(1)[0][0]
            # Require a clear repeated foreground signature in the shared prefix.
            if shared.count(key) < 3:
                continue
            for c in range(l, w):
                va, vb = grid[a][c], grid[b][c]
                if va == key and vb != key:
                    out[b][c] = 1
                elif vb == key and va != key:
                    out[a][c] = 1
    return out
